fn exec_last_occurrence_position(cafes: &Vec<i8>, cafe: i8) -> usize {
    // Since we want the *last* occurrence, we iterate from the end backwards
    // and return the first index where we find `cafe`.
    for i in (0..cafes.len()).rev() {
        if cafes[i] == cafe {
            return i;
        }
    }
    // Given the problem guarantees the value appears, returning zero as fallback.
    0
}

fn solve(cafes: Vec<i8>) -> i8 {
    use std::collections::HashSet;

    let mut seen = HashSet::new();

    // Variable to track the minimal last occurrence position found so far,
    // and the cafe (value) corresponding to it.
    let mut min_last_occurrence = usize::MAX;
    let mut result = cafes[0]; // Initialize to first element since array non-empty

    // Iterate over cafes to check last occurrence of each distinct value.
    for &cafe in &cafes {
        if seen.contains(&cafe) {
            // Skip values already processed
            continue;
        }
        seen.insert(cafe);

        let last_pos = exec_last_occurrence_position(&cafes, cafe);

        if last_pos < min_last_occurrence {
            min_last_occurrence = last_pos;
            result = cafe;
        }
    }

    result
}